import type { UnresolvedRule } from "./grammar-graph-types.ts";
import {
  isRuleChar,
  isRuleCharExclude,
  isRuleEnd,
  isRuleRef,
} from "./type-guards.ts";

export const KEY_TRANSLATION = {
