  if (isRuleCharExclude(rule)) {
    return `${KEY_TRANSLATION.RuleCharExclude}-${JSON.stringify(rule.value)}`;
  }

  if (isRuleRef(rule)) {
    return `3-${rule.value}`;
  }

  throw new Error(`Unknown rule type: ${JSON.stringify(rule)}`);
