                out_elements[last_sym_start:] = [InternalRuleDefReference(sub_rule_id)]
                self.pos = parse_space(src, self.pos + 1, is_nested)
            else:
                break

    def parse_alternates(
        self,
        rule_name: str,
        rule_id: int,
        depth: int = 0,
    ) -> None:
        src = self.src
        rule: List[InternalRuleDef] = []
