from gbnf import GBNF
from gbnf.grammar_graph.grammar_graph_types import RuleChar, RuleCharExclude, RuleEnd
from gbnf.grammar_graph.rule_ref import RuleRef
from gbnf.grammar_parser.build_rule_stack import build_rule_stack
from gbnf.rules_builder import RulesBuilder
from gbnf.utils.errors import GrammarParseError, InputParseError

def ser_internal(rule):
    name = type(rule).__name__
    if hasattr(rule, "value"):
        return {"type": name, "value": rule.value}
    return {"type": name}

def ser_rule(rule):
    if isinstance(rule, RuleEnd): return {"type": "RuleEnd"}
    if isinstance(rule, RuleChar): return {"type": "RuleChar", "value": rule.value}
    if isinstance(rule, RuleCharExclude): return {"type": "RuleCharExclude", "value": rule.value}
    if isinstance(rule, RuleRef): return {"type": "RuleRef", "value": rule.value}
    raise ValueError(f"unknown rule {rule}")

def build(grammar):
    try:
        builder = RulesBuilder(grammar)
    except GrammarParseError as err:
        return {"error": str(err)}
    rules = [[ser_internal(r) for r in rl] for rl in builder.rules]
    symbol_ids = [[k, v] for k, v in builder.symbol_ids.items()]
    stacks = [[[ser_rule(r) for r in path] for path in build_rule_stack(rl)] for rl in builder.rules]
    return {"rules": rules, "symbolIds": symbol_ids, "stacks": stacks}

def parse(grammar, inputs):
    steps = []
    try:
        state = GBNF(grammar)
    except (GrammarParseError, InputParseError) as err:
        return {"error": str(err), "steps": steps}
    steps.append({"input": None, "rules": sorted(json.dumps(ser_rule(r), sort_keys=True) for r in state)})
    for text in inputs:
        try:
            state = state.add(text)
        except (GrammarParseError, InputParseError) as err:
            steps.append({"input": text, "error": str(err)}); break
        steps.append({"input": text, "rules": sorted(json.dumps(ser_rule(r), sort_keys=True) for r in state)})
    return {"steps": steps}

